SELECT 425 f,profile,CASE WHEN pd IS NULL THEN 'nopub' WHEN g=a THEN 'same' WHEN g>a THEN 'later' ELSE 'earlier' END gc,CASE WHEN p IS NULL THEN 'null' WHEN p>=19936 THEN 'after' WHEN p>=19905 THEN 'in' WHEN p=19904 THEN 'b001' ELSE 'b002' END pb,CASE WHEN a IS NULL THEN 'null' WHEN a>=19936 THEN 'after' WHEN a>=19905 THEN 'in' WHEN a=19904 THEN 'b001' ELSE 'b002' END ab,CASE WHEN g IS NULL THEN 'null' WHEN g>=19936 THEN 'after' WHEN g>=19905 THEN 'in' WHEN g=19904 THEN 'b001' ELSE 'b002' END gb,a>p ar,g>p gr,count(*) n FROM (SELECT profile,p,pd,max(p,ifnull(q,p)) a,max(ifnull(pd,p),ifnull(rq,p),ifnull(q,p)) g FROM (SELECT n.profile profile,(n.published_at+ifnull(n.published_offset,0)*60)/86400 p,(n.dispatched_at+ifnull(n.dispatched_offset,0)*60)/86400 q,(SELECT max((d.utc_seconds+d.offset_minutes*60)/86400) FROM notice_dates d WHERE d.notice_id=n.id AND d.field_id IN ('OPP-012-notice','DE1-Publication-PublicationDate')) pd,(SELECT max((d.utc_seconds+d.offset_minutes*60)/86400) FROM notice_dates d WHERE d.notice_id=n.id AND d.field_id IN ('BT-738-notice','DE1-RequestedPublicationDate')) rq FROM notices n WHERE n.fetch_id=425 AND +n.profile<>'eforms:eforms-sdk-0.1')) GROUP BY profile,gc,pb,ab,gb,ar,gr
UNION ALL
